bool fg_json_uint(yyjson_val *obj, const char *key, size_t *out, size_t fallback) {
    yyjson_val *v = yyjson_obj_get(obj, key);
    if (!v) {
        *out = fallback;
        return true;
    }
    if (!yyjson_is_uint(v) || yyjson_get_uint(v) > SIZE_MAX)
        return false;
    *out = (size_t)yyjson_get_uint(v);
    return true;
}

